use std::fmt;

#[derive(Debug, Copy, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct Uuid(real_uuid::Uuid);

impl Uuid {
    pub fn new_v4() -> Self {
        Uuid(real_uuid::Uuid::new_v4())
    }

    pub fn to_simple_ref(&self) -> SimpleRef {
        SimpleRef(self.0)
    }

    pub fn to_hyphenated_ref(&self) -> HyphenatedRef {
        HyphenatedRef(self.0)
    }
}

pub struct SimpleRef(real_uuid::Uuid);

impl fmt::Display for SimpleRef {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.0.simple())
    }
}

impl SimpleRef {
    pub fn to_string(&self) -> String {
        self.0.simple().to_string()
    }
}

pub struct HyphenatedRef(real_uuid::Uuid);

impl fmt::Display for HyphenatedRef {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.0.hyphenated())
    }
}

impl HyphenatedRef {
    pub fn to_string(&self) -> String {
        self.0.hyphenated().to_string()
    }
}
EOF"}

